#!/usr/bin/env python3
"""
慢病平台 UI / 随访修复补丁 (demo_ux_fixes_patch)

Idempotent in-place patcher. Run from the project root:

    python3 scripts/apply_demo_ux_fixes_patch.py "$PWD"

Fixes:
  1. 顶栏窄屏换行 + 移除“当前用户：…”               apps/web/src/App.tsx, index.css
  2. 移除侧边栏“当前角色菜单范围”板块               apps/web/src/App.tsx
  3. 完成记录“查看时间线”改为跳转该任务“过去处置记录”
       apps/web/src/pages/NurseDashboardPage.tsx, PatientDetailPage.tsx,
       components/PatientHandlingHistoryView.tsx
  4. 电话随访“计划电话随访”重复任务（并发竞态）修复  apps/api/.../follow-ups.service.ts
  6. 统一任务处理中心“选择任务”卡片纵向被截断修复    apps/web/src/patient-detail-task-ux-polish.css
  7. 过去处置记录时间筛选 UI 与“历史电话沟通记录”统一
       components/PatientHandlingHistoryView.tsx, handling-history-v2.css
  8. 到院提醒“已存在有效到院提醒”UI 与下次随访时间横幅统一
       components/PatientHospitalVisitTab.tsx

Safe to re-run: edits already present are skipped. If a file has drifted from
the expected baseline, the script aborts WITHOUT modifying any file.
"""
import base64
import json
import sys
from collections import OrderedDict
from pathlib import Path

root = Path(sys.argv[1]).resolve() if len(sys.argv) > 1 else Path.cwd().resolve()

EDITS = json.loads(base64.b64decode("").decode("utf-8"))

# Group edits per file, preserving order.
by_file = OrderedDict()
for e in EDITS:
    by_file.setdefault(e["file"], []).append(e)

# Existence check first (clear message if run from the wrong directory).
missing = [rel for rel in by_file if not (root / rel).exists()]
if missing:
    raise SystemExit(
        "找不到以下文件，请在项目根目录（包含 apps/ 的目录）运行本脚本：\n  "
        + "\n  ".join(missing)
    )


def apply_one(text, edit, label):
    """Return (text, applied?). Idempotent via per-edit signal; aborts on drift."""
    sig, kind = edit["sig"], edit["kind"]
    already = (sig in text) if kind == "present" else (sig not in text)
    if already:
        return text, False          # this edit is already applied
    if edit["old"] in text:
        return text.replace(edit["old"], edit["new"], 1), True
    raise SystemExit(
        f"[{label}] 未找到预期代码，且补丁内容也不存在。\n"
        f"该文件可能已与基线不同，未修改任何文件。请人工核对后再试。"
    )


# Pass 1: compute all results in memory; abort before writing if anything fails.
results = OrderedDict()
report = OrderedDict()
for rel, edits in by_file.items():
    path = root / rel
    text = path.read_text(encoding="utf-8")
    applied = skipped = 0
    for i, e in enumerate(edits, 1):
        text, did = apply_one(text, e, f"{rel} #{i}")
        applied += int(did)
        skipped += int(not did)
    results[rel] = text
    report[rel] = (applied, skipped)

# Pass 2: write everything (only reached if every edit succeeded/was idempotent).
for rel, text in results.items():
    (root / rel).write_text(text, encoding="utf-8")

print("补丁已应用（已应用 / 已存在）：")
for rel, (a, s) in report.items():
    print(f"  {rel}: {a} applied, {s} already present")
print("\n完成。请按常规方式重新构建前端 / 后端进行验证。")
